-- --------------------------------------
-- Salvage fill: what salvaging (or opening) the items Jabbithole has no "Salvaged to" table for gives.
-- Every entry says ARCHIVE (archived Jabbithole table, the "Contains" tab of the item page) or GUESS (derived from names,
-- tooltips and the client item table, the contents are not recorded anywhere).
-- Loot groups use 1102000000-1102999999: roots from 1102000000, nested groups from 1102100000.
-- Generated by Tools/generate_salvage_fill.py. Items left empty: 22096 Deprecate
-- --------------------------------------
DELETE FROM `item_loot` WHERE `lootGroupId` BETWEEN 1102000000 AND 1102999999;
DELETE FROM `loot_item` WHERE `id` BETWEEN 1102000000 AND 1102999999;
UPDATE `loot_group` SET `parentId` = NULL WHERE `id` BETWEEN 1102000000 AND 1102999999;
DELETE FROM `loot_group` WHERE `id` BETWEEN 1102000000 AND 1102999999;

